  "invoiceNumber": "string",
  "supplierName": "string",
  "invoiceDate": "YYYY-MM-DD",
  "totalAmount": 0.00,
  "discount": 0.00,
  "netAmount": 0.00,
  "itemsCount": 0,
  "items": [
    {
      "productName": "اسم الصنف",
      "quantity": 1,
      "unitPrice": 0.00,
      "discount": 0.00,
      "totalPrice": 0.00,
      "sellingPrice": 0.00,
      "batchNumber": "string",
      "expiryDate": "YYYY-MM-DD"
    }
  ]
